use std::collections::{BTreeMap, BTreeSet};
use std::fmt::{self, Write};

use heck::{ToShoutySnakeCase, ToSnakeCase, ToUpperCamelCase};

use crate::backend::{Backend, Error, GeneratedFile};
use crate::ir::wire::{DefWire, Layout, MessageWire, StructWire, Wire};
use crate::ir::{self, DefKind, Enum, Field, Message, NamespaceId, Struct, Type, TypeId, Union};

/// The first line of every generated file.
const HEADER: &str = "// @generated by ujuc; do not edit.";

/// The module the generated code is written against, bound once per file so
/// nothing else has to name the crate.
const WIRE: &str = "uju::net::wire";

pub struct Rust;

impl Backend for Rust {
    fn generate(&self, schema: &ir::Schema) -> Result<Vec<GeneratedFile>, Error> {
        let wire = Wire::new(schema);
        let names = Names::new(schema)?;
        Ok(tree(&names)
            .iter()
            .map(|(path, node)| {
                let mut module = Module::new(schema, &wire, &names, path);
                for (index, def) in schema.defs.iter().enumerate() {
                    if node.namespaces.contains(&def.namespace) {
                        module.def(TypeId(index));
                    }
                }
                GeneratedFile::new(file_path(path), module.finish(node))
            })
            .collect())
    }
}

/// Every schema name as it is spelled in Rust.
struct Names {
    /// Rust type name of each declaration, parallel to [`ir::Schema::defs`].
    types: Vec<String>,
    /// Module path of each namespace, parallel to [`ir::Schema::namespaces`].
    modules: Vec<Vec<String>>,
}

impl Names {
    fn new(schema: &ir::Schema) -> Result<Names, Error> {
        let modules: Vec<Vec<String>> = schema
            .namespaces
            .iter()
            .map(|namespace| namespace.name.iter().map(|s| module_ident(s)).collect())
            .collect();
        let types: Vec<String> = (0..schema.defs.len())
            .map(|index| {
                let path: String = schema
                    .path(TypeId(index))
                    .iter()
                    .map(|segment| segment.to_upper_camel_case())
                    .collect();
                type_ident(&path)
            })
            .collect();

        // Nested declarations flatten into their enclosing namespace, so two
        // of them can arrive at one Rust name; the view of a union or message
        // takes a name too.
        let mut taken: BTreeMap<(&[String], String), TypeId> = BTreeMap::new();
        for (index, def) in schema.defs.iter().enumerate() {
            let id = TypeId(index);
            let module = modules[def.namespace.0].as_slice();
            let mut spellings = vec![types[index].clone()];
            if matches!(def.kind, DefKind::Union(_) | DefKind::Message(_)) {
                spellings.push(format!("{}View", types[index]));
            }
            for spelling in spellings {
                if let Some(previous) = taken.insert((module, spelling.clone()), id) {
                    return Err(Error::new(format!(
                        "`{}` and `{}` both generate the Rust type `{spelling}`",
                        qualified(schema, previous),
                        qualified(schema, id),
                    )));
                }
            }
        }
        Ok(Names { types, modules })
    }
}

/// One emitted module: the namespaces whose declarations live in it, and the
/// child modules it declares.
#[derive(Default)]
struct Node {
    /// The namespaces merged into this module, in declaration order.
    namespaces: Vec<NamespaceId>,
    children: BTreeSet<String>,
}

/// The module tree the namespaces span, keyed by module path — the root
/// included, so a schema without declarations still emits a mountable file.
fn tree(names: &Names) -> BTreeMap<Vec<String>, Node> {
    let mut nodes: BTreeMap<Vec<String>, Node> = BTreeMap::new();
    nodes.entry(Vec::new()).or_default();
    for (index, path) in names.modules.iter().enumerate() {
        for depth in 0..path.len() {
            nodes
                .entry(path[..depth].to_vec())
                .or_default()
                .children
                .insert(path[depth].clone());
            nodes.entry(path[..=depth].to_vec()).or_default();
        }
        // Segments that differ only in spelling share a module; merging is
        // kinder than emitting two files with one path.
        nodes
            .entry(path.clone())
            .or_default()
            .namespaces
            .push(NamespaceId(index));
    }
    nodes
}

fn file_path(path: &[String]) -> String {
    let mut file = String::new();
    for segment in path {
        file.push_str(segment);
        file.push('/');
    }
    file.push_str("mod.rs");
    file
}

/// Emits the declarations of one module.
struct Module<'a> {
    schema: &'a ir::Schema,
    wire: &'a Wire,
    names: &'a Names,
    /// Module path being emitted, against which other namespaces are named.
    module: &'a [String],
    out: String,
    /// Traits the emitted code calls methods of; imported anonymously, so no
    /// generated name can collide with them.
    traits: BTreeSet<&'static str>,
}

macro_rules! line {
    ($module:expr, $indent:expr, $($arg:tt)*) => {
        $module.line($indent, format_args!($($arg)*))
    };
}

impl<'a> Module<'a> {
    fn new(
        schema: &'a ir::Schema,
        wire: &'a Wire,
        names: &'a Names,
        module: &'a [String],
    ) -> Module<'a> {
        Module {
            schema,
            wire,
            names,
            module,
            out: String::new(),
            traits: BTreeSet::new(),
        }
    }

    /// The file: the header, the child modules, the imports the declarations
    /// turned out to need, and the declarations.
    fn finish(self, node: &Node) -> String {
        let mut out = String::new();
        let _ = writeln!(out, "{HEADER}");
        if !node.children.is_empty() {
            out.push('\n');
            for child in &node.children {
                let _ = writeln!(out, "pub mod {child};");
            }
        }
        if !self.out.is_empty() {
            out.push('\n');
            let _ = writeln!(out, "use {WIRE};");
            let traits: Vec<String> = self
                .traits
                .iter()
                .map(|name| format!("{name} as _"))
                .collect();
            match traits.as_slice() {
                [] => {}
                [only] => {
                    let _ = writeln!(out, "use {WIRE}::{only};");
                }
                _ => {
                    let _ = writeln!(out, "use {WIRE}::{{{}}};", traits.join(", "));
                }
            }
            out.push('\n');
            out.push_str(&self.out);
        }
        out
    }

    fn line(&mut self, indent: usize, text: impl fmt::Display) {
        for _ in 0..indent {
            self.out.push_str("    ");
        }
        let _ = writeln!(self.out, "{text}");
    }

    fn doc(&mut self, indent: usize, text: impl fmt::Display) {
        let text = text.to_string();
        if text.is_empty() {
            self.line(indent, "///");
        } else {
            self.line(indent, format_args!("/// {text}"));
        }
    }

    fn blank(&mut self) {
        self.out.push('\n');
    }

    fn def(&mut self, id: TypeId) {
        if !self.out.is_empty() {
            self.blank();
        }
        let def = self.schema.def(id);
        let name = self.names.types[id.0].clone();
        let from = qualified(self.schema, id);
        match (&def.kind, self.wire.def(id)) {
            (DefKind::Enum(item), DefWire::Enum(layout)) => {
                self.enum_def(&name, &from, item, *layout);
            }
            (DefKind::Struct(item), DefWire::Struct(item_wire)) => {
                self.struct_def(&name, &from, item, item_wire);
            }
            (DefKind::Union(item), DefWire::Union(item_wire)) => {
                self.union_def(&name, &from, item, item_wire.payload_align);
            }
            (DefKind::Message(item), DefWire::Message(item_wire)) => {
                self.message_def(&name, &from, item, item_wire);
            }
            _ => unreachable!("the wire layout is parallel to the declarations"),
        }
    }

    // ----------------------------------------------------------------- enums

    fn enum_def(&mut self, name: &str, from: &str, item: &Enum, layout: Layout) {
        let repr = item.repr.name();
        let size = layout.size;

        self.doc(0, format_args!("Generated from `{from}`."));
        self.line(0, "#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]");
        line!(self, 0, "#[repr({repr})]");
        line!(self, 0, "pub enum {name} {{");
        for variant in &item.variants {
            line!(
                self,
                1,
                "{} = {},",
                type_ident(&variant.name.to_upper_camel_case()),
                variant.value
            );
        }
        self.line(0, "}");

        self.blank();
        line!(self, 0, "impl {name} {{");
        self.doc(
            1,
            "The variant with the wire value `repr`, if there is one.",
        );
        line!(
            self,
            1,
            "pub const fn from_repr(repr: {repr}) -> Option<Self> {{"
        );
        self.line(2, "match repr {");
        for variant in &item.variants {
            line!(
                self,
                3,
                "{} => Some(Self::{}),",
                variant.value,
                type_ident(&variant.name.to_upper_camel_case())
            );
        }
        self.line(3, "_ => None,");
        self.line(2, "}");
        self.line(1, "}");
        self.blank();
        self.doc(1, "The variant's wire value.");
        line!(self, 1, "pub const fn to_repr(self) -> {repr} {{");
        line!(self, 2, "self as {repr}");
        self.line(1, "}");
        self.line(0, "}");

        self.layout_impl(name, Some(size), layout.align);

        self.blank();
        line!(self, 0, "impl wire::Wire for {name} {{");
        self.line(1, "fn encoded_size(&self) -> usize {");
        line!(self, 2, "{size}");
        self.line(1, "}");
        self.blank();
        self.line(1, "fn encode(&self, w: &mut wire::Writer) {");
        line!(self, 2, "w.push_{repr}(self.to_repr());");
        self.line(1, "}");
        self.line(0, "}");

        self.blank();
        line!(self, 0, "impl<'a> wire::View<'a> for {name} {{");
        self.line(1, "type Owned = Self;");
        self.blank();
        self.line(
            1,
            "fn read(bytes: &'a [u8], at: usize, _head: u16) -> Self {",
        );
        line!(
            self,
            2,
            "match Self::from_repr(wire::read_{repr}(bytes, at)) {{"
        );
        self.line(3, "Some(value) => value,");
        line!(self, 3, "None => panic!(\"`{name}` was not validated\"),");
        self.line(2, "}");
        self.line(1, "}");
        self.blank();
        self.line(
            1,
            "fn end(_bytes: &'a [u8], at: usize, _head: u16) -> usize {",
        );
        line!(self, 2, "at + {size}");
        self.line(1, "}");
        self.blank();
        self.line(
            1,
            "fn validate(bytes: &'a [u8], at: usize, _head: u16) -> wire::Result<usize> {",
        );
        line!(self, 2, "wire::need(bytes, at + {size})?;");
        line!(
            self,
            2,
            "if Self::from_repr(wire::read_{repr}(bytes, at)).is_none() {{"
        );
        self.line(3, "return Err(wire::Error::BadEnum);");
        self.line(2, "}");
        line!(self, 2, "Ok(at + {size})");
        self.line(1, "}");
        self.blank();
        self.line(1, "fn to_owned(self) -> Self {");
        self.line(2, "self");
        self.line(1, "}");
        self.line(0, "}");

        self.blank();
        line!(self, 0, "impl wire::Canonical for {name} {{");
        self.line(
            1,
            "fn canonical_cmp(&self, other: &Self) -> core::cmp::Ordering {",
        );
        self.line(2, "self.to_repr().cmp(&other.to_repr())");
        self.line(1, "}");
        self.line(0, "}");
    }

    // --------------------------------------------------------------- structs

    fn struct_def(&mut self, name: &str, from: &str, item: &Struct, item_wire: &StructWire) {
        let size = item_wire.layout.size;
        // Fields pack by descending alignment, so the encoder walks them in
        // offset order while the type keeps its declaration order.
        let mut packed: Vec<(&Field, usize)> = item
            .fields
            .iter()
            .zip(&item_wire.offsets)
            .map(|(field, offset)| (field, *offset))
            .collect();
        packed.sort_by_key(|(_, offset)| *offset);

        self.doc(0, format_args!("Generated from `{from}`."));
        self.line(0, "#[derive(Debug, Clone, Copy, PartialEq)]");
        if item.fields.is_empty() {
            line!(self, 0, "pub struct {name} {{}}");
        } else {
            line!(self, 0, "pub struct {name} {{");
            for field in &item.fields {
                line!(
                    self,
                    1,
                    "pub {}: {},",
                    ident(&field.name),
                    self.owned(&field.ty)
                );
            }
            self.line(0, "}");
        }

        self.layout_impl(name, Some(size), item_wire.layout.align);

        // Every fixed-size encoder advances by exactly its size, so the gaps
        // that need padding are known here.
        let mut pads = Vec::new();
        let mut end = 0;
        for (field, offset) in &packed {
            if *offset > end {
                pads.push(*offset);
            }
            end = offset + self.size(&field.ty);
        }
        if size > end {
            pads.push(size);
        }

        self.blank();
        line!(self, 0, "impl wire::Wire for {name} {{");
        self.line(1, "fn encoded_size(&self) -> usize {");
        line!(self, 2, "{size}");
        self.line(1, "}");
        self.blank();
        if item.fields.is_empty() {
            self.line(1, "fn encode(&self, _w: &mut wire::Writer) {}");
        } else {
            self.line(1, "fn encode(&self, w: &mut wire::Writer) {");
            if !pads.is_empty() {
                self.line(2, "let at = w.pos();");
            }
            let mut end = 0;
            for (field, offset) in &packed {
                if *offset > end {
                    line!(self, 2, "w.pad_to(at + {offset});");
                }
                line!(self, 2, "self.{}.encode(w);", ident(&field.name));
                end = offset + self.size(&field.ty);
            }
            if size > end {
                line!(self, 2, "w.pad_to(at + {size});");
            }
            self.line(1, "}");
        }
        self.line(0, "}");

        self.blank();
        line!(self, 0, "impl<'a> wire::View<'a> for {name} {{");
        self.line(1, "type Owned = Self;");
        self.blank();
        if item.fields.is_empty() {
            self.line(
                1,
                "fn read(_bytes: &'a [u8], _at: usize, _head: u16) -> Self {",
            );
            self.line(2, "Self {}");
        } else {
            self.line(
                1,
                "fn read(bytes: &'a [u8], at: usize, _head: u16) -> Self {",
            );
            self.line(2, "Self {");
            for (field, offset) in item.fields.iter().zip(&item_wire.offsets) {
                line!(
                    self,
                    3,
                    "{}: wire::read_fixed({}),",
                    ident(&field.name),
                    at_args("bytes", *offset)
                );
            }
            self.line(2, "}");
        }
        self.line(1, "}");
        self.blank();
        self.line(
            1,
            "fn end(_bytes: &'a [u8], at: usize, _head: u16) -> usize {",
        );
        line!(self, 2, "{}", offset("at", size));
        self.line(1, "}");
        self.blank();
        let bytes = if item.fields.is_empty() && size == 0 {
            "_bytes"
        } else {
            "bytes"
        };
        line!(
            self,
            1,
            "fn validate({bytes}: &'a [u8], at: usize, _head: u16) -> wire::Result<usize> {{"
        );
        if size > 0 {
            line!(self, 2, "wire::need(bytes, {})?;", offset("at", size));
        }
        for (field, at) in &packed {
            line!(
                self,
                2,
                "wire::validate_fixed::<{}>({})?;",
                self.view(&field.ty),
                at_args("bytes", *at)
            );
        }
        line!(self, 2, "Ok({})", offset("at", size));
        self.line(1, "}");
        self.blank();
        self.line(1, "fn to_owned(self) -> Self {");
        self.line(2, "self");
        self.line(1, "}");
        self.line(0, "}");

        self.blank();
        line!(self, 0, "impl wire::Canonical for {name} {{");
        if item.fields.is_empty() {
            self.line(
                1,
                "fn canonical_cmp(&self, _other: &Self) -> core::cmp::Ordering {",
            );
            self.line(2, "core::cmp::Ordering::Equal");
        } else {
            self.line(
                1,
                "fn canonical_cmp(&self, other: &Self) -> core::cmp::Ordering {",
            );
            for (index, field) in item.fields.iter().enumerate() {
                let name = ident(&field.name);
                if index == 0 {
                    line!(self, 2, "self.{name}.canonical_cmp(&other.{name})");
                } else {
                    line!(
                        self,
                        3,
                        ".then_with(|| self.{name}.canonical_cmp(&other.{name}))"
                    );
                }
            }
        }
        self.line(1, "}");
        self.line(0, "}");
    }

    // ---------------------------------------------------------------- unions

    fn union_def(&mut self, name: &str, from: &str, item: &Union, align: usize) {
        let view = format!("{name}View");
        let variants: Vec<String> = item
            .members
            .iter()
            .map(|member| type_ident(&member.name.to_upper_camel_case()))
            .collect();
        let accessors: BTreeSet<String> = item
            .members
            .iter()
            .map(|member| ident(&member.name))
            .collect();
        let tag = unique("tag", &accessors);

        self.doc(0, format_args!("Generated from `{from}`."));
        if item.members.iter().any(|member| self.is_boxed(&member.ty)) {
            self.doc(0, "");
            self.doc(
                0,
                "A member that is itself a union is boxed, since a union may",
            );
            self.doc(0, "reach itself.");
        }
        self.line(0, "#[derive(Debug, Clone, PartialEq)]");
        line!(self, 0, "pub enum {name} {{");
        for (member, variant) in item.members.iter().zip(&variants) {
            line!(self, 1, "{variant}({}),", self.member_owned(&member.ty));
        }
        self.line(0, "}");

        self.blank();
        line!(self, 0, "impl {name} {{");
        for (index, member) in item.members.iter().enumerate() {
            if index > 0 {
                self.blank();
            }
            self.doc(1, format_args!("Tag of the `{}` member.", member.name));
            line!(
                self,
                1,
                "pub const TAG_{}: u16 = {index};",
                member.name.to_shouty_snake_case()
            );
        }
        if !item.members.is_empty() {
            self.blank();
        }
        self.doc(1, "The set member's tag: its declaration index.");
        line!(self, 1, "pub const fn {tag}(&self) -> u16 {{");
        self.line(2, "match self {");
        for (member, variant) in item.members.iter().zip(&variants) {
            line!(
                self,
                3,
                "Self::{variant}(_) => Self::TAG_{},",
                member.name.to_shouty_snake_case()
            );
        }
        self.line(2, "}");
        self.line(1, "}");
        self.line(0, "}");

        self.layout_impl(name, None, align);

        self.blank();
        line!(self, 0, "impl wire::Wire for {name} {{");
        self.line(1, "fn encoded_size(&self) -> usize {");
        self.line(2, "match self {");
        for (member, variant) in item.members.iter().zip(&variants) {
            line!(
                self,
                3,
                "Self::{variant}(value) => wire::element_size({}),",
                self.member_value(&member.ty)
            );
        }
        self.line(2, "}");
        self.line(1, "}");
        self.blank();
        self.line(1, "fn encode(&self, w: &mut wire::Writer) {");
        self.line(2, "match self {");
        for (member, variant) in item.members.iter().zip(&variants) {
            line!(
                self,
                3,
                "Self::{variant}(value) => wire::encode_element({}, w),",
                self.member_value(&member.ty)
            );
        }
        self.line(2, "}");
        self.line(1, "}");
        self.blank();
        self.line(1, "fn head(&self) -> usize {");
        line!(self, 2, "self.{tag}() as usize");
        self.line(1, "}");
        self.line(0, "}");

        self.blank();
        self.doc(0, format_args!("A zero-copy view of [`{name}`]."));
        self.line(0, "#[derive(Clone, Copy)]");
        line!(self, 0, "pub struct {view}<'a> {{");
        self.line(1, "bytes: &'a [u8],");
        self.line(1, "at: usize,");
        self.line(1, "tag: u16,");
        self.line(0, "}");

        self.blank();
        line!(self, 0, "impl<'a> {view}<'a> {{");
        self.doc(1, "The set member's tag: its declaration index.");
        line!(self, 1, "pub fn {tag}(self) -> u16 {{");
        self.line(2, "self.tag");
        self.line(1, "}");
        for (index, member) in item.members.iter().enumerate() {
            self.blank();
            self.doc(
                1,
                format_args!("The `{}` member, if it is the one set.", member.name),
            );
            line!(
                self,
                1,
                "pub fn {}(self) -> Option<{}> {{",
                ident(&member.name),
                self.view(&member.ty)
            );
            line!(
                self,
                2,
                "(self.tag == {index}).then(|| wire::read_element(self.bytes, self.at))"
            );
            self.line(1, "}");
        }
        self.line(0, "}");

        self.layout_impl(&format!("{view}<'a>"), None, align);

        self.blank();
        line!(self, 0, "impl<'a> wire::View<'a> for {view}<'a> {{");
        line!(self, 1, "type Owned = {name};");
        self.blank();
        self.line(
            1,
            "fn read(bytes: &'a [u8], at: usize, head: u16) -> Self {",
        );
        self.line(2, "Self {");
        self.line(3, "bytes,");
        self.line(3, "at,");
        self.line(3, "tag: head,");
        self.line(2, "}");
        self.line(1, "}");
        self.blank();
        self.line(
            1,
            "fn end(bytes: &'a [u8], at: usize, head: u16) -> usize {",
        );
        self.line(2, "match head {");
        for (index, member) in item.members.iter().enumerate() {
            line!(
                self,
                3,
                "{index} => wire::element_end::<{}>(bytes, at),",
                self.view(&member.ty)
            );
        }
        self.line(3, "_ => at,");
        self.line(2, "}");
        self.line(1, "}");
        self.blank();
        self.line(
            1,
            "fn validate(bytes: &'a [u8], at: usize, head: u16) -> wire::Result<usize> {",
        );
        self.line(2, "match head {");
        for (index, member) in item.members.iter().enumerate() {
            line!(
                self,
                3,
                "{index} => wire::validate_element::<{}>(bytes, at),",
                self.view(&member.ty)
            );
        }
        self.line(3, "_ => Err(wire::Error::BadTag),");
        self.line(2, "}");
        self.line(1, "}");
        self.blank();
        line!(self, 1, "fn to_owned(self) -> {name} {{");
        self.line(2, "match self.tag {");
        for (index, (member, variant)) in item.members.iter().zip(&variants).enumerate() {
            let read = format!(
                "wire::read_element::<{}>(self.bytes, self.at)",
                self.view(&member.ty)
            );
            line!(
                self,
                3,
                "{index} => {name}::{variant}({}),",
                self.member_owned_expr(&member.ty, &read)
            );
        }
        line!(self, 3, "_ => panic!(\"`{name}` was not validated\"),");
        self.line(2, "}");
        self.line(1, "}");
        self.line(0, "}");
    }

    // -------------------------------------------------------------- messages

    fn message_def(&mut self, name: &str, from: &str, item: &Message, item_wire: &MessageWire) {
        let view = format!("{name}View");
        let fixed_size = item_wire.fixed_size;

        // Fixed fields are written in offset order; variable ones keep
        // declaration order, which is the order their payloads follow in.
        let mut fixed: Vec<(usize, &Field)> = Vec::new();
        let mut variable: Vec<(usize, &Field)> = Vec::new();
        for (index, field) in item.fields.iter().enumerate() {
            if self.is_fixed(&field.ty) {
                fixed.push((index, field));
            } else {
                variable.push((index, field));
            }
        }
        fixed.sort_by_key(|(index, _)| item_wire.fields[*index].offset);

        self.doc(0, format_args!("Generated from `{from}`."));
        self.line(0, "#[derive(Debug, Clone, PartialEq)]");
        if item.fields.is_empty() {
            line!(self, 0, "pub struct {name} {{}}");
        } else {
            line!(self, 0, "pub struct {name} {{");
            for field in &item.fields {
                line!(
                    self,
                    1,
                    "pub {}: {},",
                    ident(&field.name),
                    self.field_owned(field)
                );
            }
            self.line(0, "}");
        }

        self.blank();
        line!(self, 0, "impl wire::Message for {name} {{");
        line!(self, 1, "type View<'a> = {view}<'a>;");
        self.blank();
        line!(self, 1, "const ALIGN: usize = {};", item_wire.align);
        self.blank();
        self.line(1, "fn encoded_size(&self) -> usize {");
        if variable.is_empty() {
            line!(self, 2, "{fixed_size}");
        } else {
            self.traits.insert("Wire");
            line!(self, 2, "let mut at = {fixed_size};");
            for (_, field) in &variable {
                let align = self.wire.payload_align(&field.ty);
                let name = ident(&field.name);
                if field.optional {
                    line!(self, 2, "if let Some(value) = &self.{name} {{");
                    self.line(3, grow("value", align));
                    self.line(2, "}");
                } else {
                    self.line(2, grow(&format!("self.{name}"), align));
                }
            }
            self.line(2, "at");
        }
        self.line(1, "}");
        self.blank();
        self.message_write(item, item_wire, &fixed, &variable);
        self.line(0, "}");

        // The view: the buffer, and an accessor per field.
        let accessors: BTreeSet<String> = item.fields.iter().map(|f| ident(&f.name)).collect();
        let payload_at = unique("payload_at", &accessors);

        self.blank();
        self.doc(0, format_args!("A zero-copy view of [`{name}`]."));
        self.line(0, "#[derive(Clone, Copy)]");
        if item.fields.is_empty() {
            // A message without fields carries nothing to borrow.
            line!(
                self,
                0,
                "pub struct {view}<'a>(core::marker::PhantomData<&'a [u8]>);"
            );
        } else {
            line!(self, 0, "pub struct {view}<'a> {{");
            self.line(1, "bytes: &'a [u8],");
            self.line(0, "}");

            self.blank();
            line!(self, 0, "impl<'a> {view}<'a> {{");
            for (index, field) in item.fields.iter().enumerate() {
                if index > 0 {
                    self.blank();
                }
                self.accessor(field, item_wire, index, &payload_at);
            }
            if !variable.is_empty() {
                self.blank();
                self.payload_at(item_wire, &variable, &payload_at);
            }
            self.line(0, "}");
        }

        self.blank();
        line!(self, 0, "impl<'a> wire::MessageView<'a> for {view}<'a> {{");
        line!(self, 1, "type Owned = {name};");
        self.blank();
        if item.fields.is_empty() {
            self.line(1, "fn read(_bytes: &'a [u8]) -> Self {");
            self.line(2, "Self(core::marker::PhantomData)");
        } else {
            self.line(1, "fn read(bytes: &'a [u8]) -> Self {");
            self.line(2, "Self { bytes }");
        }
        self.line(1, "}");
        self.blank();
        self.message_validate(item, item_wire, &fixed, &variable);
        self.blank();
        line!(self, 1, "fn to_owned(self) -> {name} {{");
        if item.fields.is_empty() {
            line!(self, 2, "{name} {{}}");
            self.line(1, "}");
            self.line(0, "}");
            return;
        }
        line!(self, 2, "{name} {{");
        for field in &item.fields {
            let name = ident(&field.name);
            // `to_owned` is qualified: for `&str` and `&[u8]` the method call
            // would be ambiguous with `ToOwned::to_owned`.
            let value = match (self.is_fixed(&field.ty), field.optional) {
                (true, _) => format!("self.{name}()"),
                (false, false) => format!("wire::View::to_owned(self.{name}())"),
                (false, true) => format!("self.{name}().map(wire::View::to_owned)"),
            };
            line!(self, 3, "{name}: {value},");
        }
        self.line(2, "}");
        self.line(1, "}");
        self.line(0, "}");
    }

    /// The fixed section — fields, presence bits, slots — then the payloads.
    fn message_write(
        &mut self,
        item: &Message,
        item_wire: &MessageWire,
        fixed: &[(usize, &Field)],
        variable: &[(usize, &Field)],
    ) {
        if item.fields.is_empty() {
            self.line(1, "fn write(&self, _w: &mut wire::Writer) {}");
            return;
        }
        self.traits.insert("Wire");
        self.line(1, "fn write(&self, w: &mut wire::Writer) {");

        // Absent optional fields are zero-filled rather than skipped, so the
        // writer's position stays known and `validate` can check the hole.
        let mut end = 0;
        for (index, field) in fixed {
            let at = item_wire.fields[*index].offset;
            if at > end {
                line!(self, 2, "w.pad_to({at});");
            }
            let name = ident(&field.name);
            let size = self.size(&field.ty);
            if field.optional {
                line!(self, 2, "match &self.{name} {{");
                self.line(3, "Some(value) => value.encode(w),");
                line!(self, 3, "None => w.push_zeros({size}),");
                self.line(2, "}");
            } else {
                line!(self, 2, "self.{name}.encode(w);");
            }
            end = at + size;
        }

        if item_wire.presence_bytes > 0 {
            if item_wire.presence_offset > end {
                line!(self, 2, "w.pad_to({});", item_wire.presence_offset);
            }
            line!(
                self,
                2,
                "let mut presence = [0u8; {}];",
                item_wire.presence_bytes
            );
            for (index, field) in item.fields.iter().enumerate() {
                if let Some(bit) = item_wire.fields[index].presence {
                    line!(self, 2, "if self.{}.is_some() {{", ident(&field.name));
                    line!(self, 3, "presence[{}] |= 1 << {};", bit / 8, bit % 8);
                    self.line(2, "}");
                }
            }
            self.line(2, "w.push_bytes(&presence);");
            end = item_wire.presence_offset + item_wire.presence_bytes;
        }

        for (position, (index, field)) in variable.iter().enumerate() {
            let slot = item_wire.fields[*index].offset;
            if position == 0 && slot > end {
                line!(self, 2, "w.pad_to({slot});");
            }
            let name = ident(&field.name);
            if field.optional {
                line!(self, 2, "match &self.{name} {{");
                self.line(3, "Some(value) => w.push_head(value.head()),");
                self.line(3, "None => w.push_u16(0),");
                self.line(2, "}");
            } else {
                line!(self, 2, "w.push_head(self.{name}.head());");
            }
        }

        for (_, field) in variable {
            let align = self.wire.payload_align(&field.ty);
            let name = ident(&field.name);
            if field.optional {
                line!(self, 2, "if let Some(value) = &self.{name} {{");
                if align > 1 {
                    line!(self, 3, "w.align({align});");
                }
                self.line(3, "value.encode(w);");
                self.line(2, "}");
            } else {
                if align > 1 {
                    line!(self, 2, "w.align({align});");
                }
                line!(self, 2, "self.{name}.encode(w);");
            }
        }
        self.line(1, "}");
    }

    /// One accessor: a fixed-size field reads inline, a variable-size one
    /// pairs its slot with the payload the walk lands on.
    fn accessor(&mut self, field: &Field, item_wire: &MessageWire, index: usize, payload: &str) {
        let name = ident(&field.name);
        let at = item_wire.fields[index].offset;
        let presence = item_wire.fields[index]
            .presence
            .map(|bit| test_bit("self.bytes", item_wire.presence_offset, bit));
        let ty = self.view(&field.ty);
        let read = if self.is_fixed(&field.ty) {
            format!("wire::read_fixed({})", abs_args("self.bytes", at))
        } else {
            format!(
                "wire::read_value(self.bytes, self.{payload}({index}), wire::read_u16({}))",
                abs_args("self.bytes", at)
            )
        };
        match presence {
            None => {
                line!(self, 1, "pub fn {name}(self) -> {ty} {{");
                line!(self, 2, "{read}");
            }
            Some(test) => {
                line!(self, 1, "pub fn {name}(self) -> Option<{ty}> {{");
                line!(self, 2, "{test}");
                line!(self, 3, ".then(|| {read})");
            }
        }
        self.line(1, "}");
    }

    /// The payload walk: each variable-size field's payload sits past the one
    /// before it, padded to its own alignment. An absent optional field takes
    /// no payload and no padding.
    fn payload_at(
        &mut self,
        item_wire: &MessageWire,
        variable: &[(usize, &Field)],
        payload_at: &str,
    ) {
        self.doc(
            1,
            "Offset of the payload of the variable-size field at declaration",
        );
        self.doc(1, "index `field`, or of the message end past the last one.");
        line!(self, 1, "fn {payload_at}(self, field: usize) -> usize {{");
        line!(self, 2, "let mut at = {};", item_wire.fixed_size);
        for (index, field) in variable {
            let align = self.wire.payload_align(&field.ty);
            let slot = item_wire.fields[*index].offset;
            let head = format!("wire::read_u16({})", abs_args("self.bytes", slot));
            let end = format!(
                "wire::value_end::<{}>(self.bytes, payload, {head})",
                self.view(&field.ty)
            );
            if align > 1 {
                line!(self, 2, "let payload = wire::pad(at, {align});");
            } else {
                self.line(2, "let payload = at;");
            }
            line!(self, 2, "if field == {index} {{");
            self.line(3, "return payload;");
            self.line(2, "}");
            match item_wire.fields[*index].presence {
                None => line!(self, 2, "at = {end};"),
                Some(bit) => {
                    line!(
                        self,
                        2,
                        "if {} {{",
                        test_bit("self.bytes", item_wire.presence_offset, bit)
                    );
                    line!(self, 3, "at = {end};");
                    self.line(2, "}");
                }
            }
        }
        self.line(2, "at");
        self.line(1, "}");
    }

    fn message_validate(
        &mut self,
        item: &Message,
        item_wire: &MessageWire,
        fixed: &[(usize, &Field)],
        variable: &[(usize, &Field)],
    ) {
        let used = item_wire.fixed_size > 0 || !item.fields.is_empty();
        let bytes = if used { "bytes" } else { "_bytes" };
        line!(
            self,
            1,
            "fn validate({bytes}: &'a [u8]) -> wire::Result<usize> {{"
        );
        if item_wire.fixed_size > 0 {
            line!(self, 2, "wire::need(bytes, {})?;", item_wire.fixed_size);
        }
        for (index, field) in fixed {
            let at = item_wire.fields[*index].offset;
            let ty = self.view(&field.ty);
            let check = format!("wire::validate_fixed::<{ty}>({})?;", abs_args("bytes", at));
            match item_wire.fields[*index].presence {
                None => self.line(2, check),
                Some(bit) => {
                    line!(
                        self,
                        2,
                        "if {} {{",
                        test_bit("bytes", item_wire.presence_offset, bit)
                    );
                    self.line(3, check);
                    line!(
                        self,
                        2,
                        "}} else if !wire::is_zero(bytes, {at}, {}) {{",
                        self.size(&field.ty)
                    );
                    self.line(3, "return Err(wire::Error::BadPadding);");
                    self.line(2, "}");
                }
            }
        }
        if variable.is_empty() {
            line!(self, 2, "Ok({})", item_wire.fixed_size);
        } else {
            line!(self, 2, "let mut at = {};", item_wire.fixed_size);
            for (index, field) in variable {
                let align = self.wire.payload_align(&field.ty);
                let slot = item_wire.fields[*index].offset;
                let payload = if align > 1 {
                    format!("wire::pad(at, {align})")
                } else {
                    "at".to_string()
                };
                let ty = self.view(&field.ty);
                match item_wire.fields[*index].presence {
                    None => line!(
                        self,
                        2,
                        "at = wire::validate_value::<{ty}>(bytes, {payload}, wire::read_u16({}))?;",
                        abs_args("bytes", slot)
                    ),
                    Some(bit) => {
                        line!(
                            self,
                            2,
                            "let head = wire::read_u16({});",
                            abs_args("bytes", slot)
                        );
                        line!(
                            self,
                            2,
                            "if {} {{",
                            test_bit("bytes", item_wire.presence_offset, bit)
                        );
                        line!(
                            self,
                            3,
                            "at = wire::validate_value::<{ty}>(bytes, {payload}, head)?;"
                        );
                        self.line(2, "} else if head != 0 {");
                        self.line(3, "return Err(wire::Error::BadPadding);");
                        self.line(2, "}");
                    }
                }
            }
            self.line(2, "Ok(at)");
        }
        self.line(1, "}");
    }

    // ----------------------------------------------------------------- names

    fn layout_impl(&mut self, name: &str, size: Option<usize>, align: usize) {
        let generic = if name.contains('<') { "<'a>" } else { "" };
        let fixed = match size {
            Some(size) => format!("Some({size})"),
            None => "None".to_string(),
        };
        self.blank();
        line!(self, 0, "impl{generic} wire::Layout for {name} {{");
        line!(self, 1, "const FIXED_SIZE: Option<usize> = {fixed};");
        line!(self, 1, "const ALIGN: usize = {align};");
        self.line(0, "}");
    }

    /// The Rust path of a declaration, from the module being emitted.
    fn path(&self, id: TypeId) -> String {
        let name = &self.names.types[id.0];
        let module = &self.names.modules[self.schema.def(id).namespace.0];
        if module.as_slice() == self.module {
            return name.clone();
        }
        let mut path = "super::".repeat(self.module.len());
        for segment in module {
            path.push_str(segment);
            path.push_str("::");
        }
        path.push_str(name);
        path
    }

    /// The owned Rust type of `ty`.
    fn owned(&self, ty: &Type) -> String {
        match ty {
            Type::I8 => "i8".to_string(),
            Type::I16 => "i16".to_string(),
            Type::I32 => "i32".to_string(),
            Type::I64 => "i64".to_string(),
            Type::U8 => "u8".to_string(),
            Type::U16 => "u16".to_string(),
            Type::U32 => "u32".to_string(),
            Type::U64 => "u64".to_string(),
            Type::F32 => "f32".to_string(),
            Type::F64 => "f64".to_string(),
            Type::Bool => "bool".to_string(),
            Type::Timestamp => "wire::Timestamp".to_string(),
            Type::Interval => "wire::Interval".to_string(),
            Type::Entity => "wire::Entity".to_string(),
            Type::UEntity => "wire::UniversalEntity".to_string(),
            Type::Uuid => "wire::Uuid".to_string(),
            Type::String => "String".to_string(),
            Type::Bytes => "Vec<u8>".to_string(),
            Type::Array(item, len) => format!("[{}; {len}]", self.owned(item)),
            Type::Vec(item) => format!("Vec<{}>", self.owned(item)),
            Type::Set(item) => format!("wire::Set<{}>", self.owned(item)),
            Type::Map(key, value) => {
                format!("wire::Map<{}, {}>", self.owned(key), self.owned(value))
            }
            Type::Named(id) => self.path(*id),
        }
    }

    /// The view type of `ty`, borrowing the message buffer for `'a`.
    fn view(&self, ty: &Type) -> String {
        match ty {
            Type::String => "&'a str".to_string(),
            Type::Bytes => "&'a [u8]".to_string(),
            Type::Array(item, len) => format!("[{}; {len}]", self.view(item)),
            Type::Vec(item) => format!("wire::VecView<'a, {}>", self.view(item)),
            Type::Set(item) => format!("wire::SetView<'a, {}>", self.view(item)),
            Type::Map(key, value) => {
                format!(
                    "wire::MapView<'a, {}, {}>",
                    self.view(key),
                    self.view(value)
                )
            }
            Type::Named(id) if self.is_union(*id) => format!("{}View<'a>", self.path(*id)),
            _ => self.owned(ty),
        }
    }

    /// The owned type of a message field, which an optional field wraps.
    fn field_owned(&self, field: &Field) -> String {
        let ty = self.owned(&field.ty);
        if field.optional {
            format!("Option<{ty}>")
        } else {
            ty
        }
    }

    /// The owned type a union variant holds; a member that is itself a union
    /// is boxed, since a union may reach itself.
    fn member_owned(&self, ty: &Type) -> String {
        if self.is_boxed(ty) {
            format!("Box<{}>", self.owned(ty))
        } else {
            self.owned(ty)
        }
    }

    /// A union member bound as `value`, as a reference to the member itself.
    fn member_value(&self, ty: &Type) -> &'static str {
        if self.is_boxed(ty) {
            "value.as_ref()"
        } else {
            "value"
        }
    }

    /// A union member read as `read`, owned and boxed as its variant holds it.
    fn member_owned_expr(&self, ty: &Type, read: &str) -> String {
        let owned = if self.is_fixed(ty) {
            read.to_string()
        } else {
            format!("wire::View::to_owned({read})")
        };
        if self.is_boxed(ty) {
            format!("Box::new({owned})")
        } else {
            owned
        }
    }

    fn is_boxed(&self, ty: &Type) -> bool {
        matches!(ty, Type::Named(id) if self.is_union(*id))
    }

    fn is_union(&self, id: TypeId) -> bool {
        matches!(self.schema.def(id).kind, DefKind::Union(_))
    }

    fn is_fixed(&self, ty: &Type) -> bool {
        self.wire.is_fixed(ty)
    }

    fn size(&self, ty: &Type) -> usize {
        self.wire.layout(ty).size
    }
}

/// `at` grown past a payload of `align`-aligned `value`.
fn grow(value: &str, align: usize) -> String {
    if align > 1 {
        format!("at = wire::pad(at, {align}) + {value}.encoded_size();")
    } else {
        format!("at += {value}.encoded_size();")
    }
}

/// `bytes, at + n` as an argument list, for a value read at a runtime offset.
fn at_args(bytes: &str, at: usize) -> String {
    format!("{bytes}, {}", offset("at", at))
}

/// `bytes, n` as an argument list, for a message's constant offsets.
fn abs_args(bytes: &str, at: usize) -> String {
    format!("{bytes}, {at}")
}

/// `base + at`, or just `base` when `at` is zero.
fn offset(base: &str, at: usize) -> String {
    if at == 0 {
        base.to_string()
    } else {
        format!("{base} + {at}")
    }
}

/// The presence bit of an optional field, read from `bytes`.
fn test_bit(bytes: &str, presence: usize, bit: u32) -> String {
    format!("wire::test_bit({bytes}, {presence}, {bit})")
}

/// A declaration's namespace, the declarations it is nested in, and its own
/// name, joined with `.` — the schema's spelling, for doc comments.
fn qualified(schema: &ir::Schema, id: TypeId) -> String {
    let mut name = schema.namespace(schema.def(id).namespace).name.join(".");
    for segment in schema.path(id) {
        name.push('.');
        name.push_str(segment);
    }
    name
}

/// Rust's keywords, which a schema name is free to use.
const KEYWORDS: &[&str] = &[
    "abstract", "as", "async", "await", "become", "box", "break", "const", "continue", "do", "dyn",
    "else", "enum", "extern", "false", "final", "fn", "for", "gen", "if", "impl", "in", "let",
    "loop", "macro", "match", "mod", "move", "mut", "override", "priv", "pub", "ref", "return",
    "static", "struct", "trait", "true", "try", "type", "typeof", "unsafe", "unsized", "use",
    "virtual", "where", "while", "yield",
];

/// The keywords a raw identifier cannot spell.
const RESERVED: &[&str] = &["crate", "self", "Self", "super"];

/// A field or member name as a Rust identifier.
fn ident(name: &str) -> String {
    let name = name.to_snake_case();
    if RESERVED.contains(&name.as_str()) {
        format!("{name}_")
    } else if KEYWORDS.contains(&name.as_str()) {
        format!("r#{name}")
    } else {
        name
    }
}

/// A namespace segment as a module name. Raw identifiers are avoided here,
/// since the module name is also the directory name.
fn module_ident(name: &str) -> String {
    let name = name.to_snake_case();
    if RESERVED.contains(&name.as_str()) || KEYWORDS.contains(&name.as_str()) {
        format!("{name}_")
    } else {
        name
    }
}

/// An already camel-cased name as a Rust type name.
fn type_ident(name: &str) -> String {
    if RESERVED.contains(&name) || KEYWORDS.contains(&name) {
        format!("{name}_")
    } else {
        name.to_string()
    }
}

/// A method name that no accessor has taken.
fn unique(name: &str, taken: &BTreeSet<String>) -> String {
    let mut name = name.to_string();
    while taken.contains(&name) {
        name.push('_');
    }
    name
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::compile;

    const SAMPLE1: &str = include_str!("../../tests/data/sample1.uju");
    const SAMPLE2: &str = include_str!("../../tests/data/sample2.uju");

    fn generated(sources: &[&str]) -> Vec<GeneratedFile> {
        let schema =
            compile(sources).unwrap_or_else(|errors| panic!("unexpected errors: {errors:#?}"));
        Rust.generate(&schema).expect("the samples generate")
    }

    fn file(sources: &[&str], path: &str) -> String {
        generated(sources)
            .into_iter()
            .find(|file| file.path.as_os_str() == path)
            .unwrap_or_else(|| panic!("no generated `{path}`"))
            .contents
    }

    fn only(sources: &[&str]) -> String {
        let files = generated(sources);
        let modules: Vec<_> = files
            .iter()
            .filter(|file| !file.contents.contains("pub mod "))
            .collect();
        assert_eq!(modules.len(), 1, "expected a single module of declarations");
        modules[0].contents.clone()
    }

    #[test]
    fn namespaces_become_a_module_tree() {
        let files = generated(&[SAMPLE1, SAMPLE2]);
        let paths: Vec<_> = files
            .iter()
            .map(|file| file.path.display().to_string())
            .collect();
        assert_eq!(
            paths,
            ["mod.rs", "foo/mod.rs", "foo/bar/mod.rs", "hello/mod.rs"]
        );
        assert!(file(&[SAMPLE1, SAMPLE2], "mod.rs").contains("pub mod foo;"));
        assert!(file(&[SAMPLE1, SAMPLE2], "foo/mod.rs").contains("pub mod bar;"));
    }

    #[test]
    fn every_file_is_marked_generated() {
        for file in generated(&[SAMPLE1, SAMPLE2]) {
            assert!(file.contents.starts_with(HEADER), "{}", file.contents);
        }
    }

    #[test]
    fn other_namespaces_are_named_through_the_root() {
        let hello = file(&[SAMPLE1, SAMPLE2], "hello/mod.rs");
        assert!(
            hello.contains("pub position: super::foo::bar::Position,"),
            "{hello}"
        );
    }

    #[test]
    fn enums_carry_their_repr_and_values() {
        let contents = only(&[SAMPLE1]);
        assert!(
            contents.contains("#[repr(u8)]\npub enum Color {"),
            "{contents}"
        );
        assert!(contents.contains("    Blue = 5,"), "{contents}");
        assert!(
            contents.contains("pub const fn from_repr(repr: u8) -> Option<Self>"),
            "{contents}"
        );
    }

    #[test]
    fn structs_read_at_their_packed_offsets() {
        let contents = only(&["namespace a;\nstruct S { a: u8, b: u32 }\n"]);
        assert!(contents.contains("const FIXED_SIZE: Option<usize> = Some(8);"));
        assert!(
            contents.contains("a: wire::read_fixed(bytes, at + 4),"),
            "{contents}"
        );
        assert!(
            contents.contains("b: wire::read_fixed(bytes, at),"),
            "{contents}"
        );
    }

    #[test]
    fn fixed_size_declarations_are_their_own_view() {
        let contents = only(&["namespace a;\nstruct S { a: u8 }\n"]);
        assert!(
            contents.contains("impl<'a> wire::View<'a> for S {"),
            "{contents}"
        );
        assert!(contents.contains("type Owned = Self;"), "{contents}");
        assert!(!contents.contains("SView"), "{contents}");
    }

    #[test]
    fn nested_declarations_flatten_into_one_name() {
        let contents = only(&[SAMPLE1]);
        assert!(
            contents.contains("pub enum MyResponseResult {"),
            "{contents}"
        );
        assert!(
            contents.contains("pub result: MyResponseResult,"),
            "{contents}"
        );
    }

    #[test]
    fn variable_size_fields_pair_a_slot_with_a_payload() {
        let contents = only(&["namespace a;\nmessage M { v: vec<u64>, s: string }\n"]);
        assert!(
            contents.contains(
                "wire::read_value(self.bytes, self.payload_at(0), wire::read_u16(self.bytes, 0))"
            ),
            "{contents}"
        );
        assert!(
            contents.contains("let payload = wire::pad(at, 8);"),
            "{contents}"
        );
        assert!(
            contents.contains("at = wire::value_end::<wire::VecView<'a, u64>>"),
            "{contents}"
        );
    }

    #[test]
    fn optional_fields_are_gated_on_their_presence_bit() {
        let contents = only(&["namespace a;\nmessage M { a: i32?, v: vec<i32>? }\n"]);
        assert!(contents.contains("pub a: Option<i32>,"), "{contents}");
        assert!(
            contents.contains("wire::test_bit(self.bytes, 4, 0)"),
            "{contents}"
        );
        assert!(contents.contains("None => w.push_zeros(4),"), "{contents}");
        assert!(
            contents.contains("} else if !wire::is_zero(bytes, 0, 4) {"),
            "{contents}"
        );
        assert!(
            contents.contains("return Err(wire::Error::BadPadding);"),
            "{contents}"
        );
    }

    #[test]
    fn unions_read_a_member_by_tag() {
        let contents = only(&[SAMPLE1]);
        assert!(
            contents.contains("pub const TAG_VEL: u16 = 2;"),
            "{contents}"
        );
        assert!(
            contents.contains("pub fn vel(self) -> Option<Velocity> {"),
            "{contents}"
        );
        assert!(
            contents.contains("_ => Err(wire::Error::BadTag),"),
            "{contents}"
        );
    }

    #[test]
    fn a_union_member_that_is_a_union_is_boxed() {
        let contents = only(&["namespace a;\nunion A { b: B, x: i64 }\nunion B { a: A }\n"]);
        assert!(contents.contains("B(Box<B>),"), "{contents}");
        assert!(
            contents.contains("wire::element_size(value.as_ref())"),
            "{contents}"
        );
    }

    #[test]
    fn container_views_nest() {
        let contents = only(&["namespace a;\nmessage M { m: map<u8, vec<string>> }\n"]);
        assert!(
            contents.contains("wire::MapView<'a, u8, wire::VecView<'a, &'a str>>"),
            "{contents}"
        );
        assert!(
            contents.contains("pub m: wire::Map<u8, Vec<String>>,"),
            "{contents}"
        );
    }

    #[test]
    fn schema_names_that_are_rust_keywords_are_escaped() {
        let contents = only(&["namespace a;\nmessage M { type: u8, self: u8 }\n"]);
        assert!(contents.contains("pub r#type: u8,"), "{contents}");
        assert!(contents.contains("pub self_: u8,"), "{contents}");
    }

    #[test]
    fn colliding_rust_names_are_reported() {
        let schema = compile(&[
            "namespace a;\nmessage Outer { enum Kind { X } k: Kind }\nenum OuterKind { Y }\n",
        ])
        .expect("the schema itself is valid");
        let error = Rust.generate(&schema).expect_err("the names collide");
        assert!(error.message.contains("OuterKind"), "{}", error.message);
    }
}
